import {copyFrameCases,copyFrameCase,copyFrameCopy as copy} from './copy-frame-content.mjs';
import {createCopyFrame,copyFrameModel,changeCopySide,turnCopyFrame,resetCopyMaterial,copyFrameReading,copyFrameExample,copyFactorText,copyLength,copyArea} from './copy-frame-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null;
export function resetCopyFrame(){visit=null;}
function current(notebook,owner){
 if(!visit||visit.notebook!==notebook||visit.owner!==owner)visit={notebook,owner,caseId:'small-panel',cases:new Map(),example:false,frame:0,pending:''};
 if(!visit.cases.has(visit.caseId))visit.cases.set(visit.caseId,{material:createCopyFrame(visit.caseId),tiles:false,read:false});
 return visit;
}
const button=(action,label,disabled=false,description='')=>`<button type="button" data-cframe-action="${action}"${disabled?' disabled':''}${description?` aria-describedby="${description}"`:''}>${esc(label)}</button>`;
function references(m,example=false){return `<div class="cframe-refs" data-cframe-read><p><strong>${example?'Example original':'Original panel'}:</strong> width ${copyLength(m.originalWidth)}; height ${copyLength(m.originalHeight)}.</p> <p><strong>${example?'Example copy':'My copy'}:</strong> width ${copyLength(m.width)}; height ${copyLength(m.height)}.</p></div>`;}
function drawing(m,tiles,example=false){
 const u=22,x=26,y=290;
 const rect=(w,h)=>`x="${x}" y="${y-h*u}" width="${w*u}" height="${h*u}"`;
 const grid=Array.from({length:13},(_,i)=>`<path d="M${x+i*u} ${y-12*u}V${y}M${x} ${y-i*u}H${x+12*u}"/>`).join('');
 const cells=tiles?m.cells.map(c=>`<rect data-cframe-cell x="${x+c.x*u}" y="${y-(c.y+1)*u}" width="${u}" height="${u}" fill="${(c.x+c.y)%2?'#eaf4ef':'#c5e3d9'}" stroke="#397958" stroke-width=".75"/>`).join(''):'';
 const panels=(m.panels||[]).map(p=>`<rect data-cframe-panel x="${x+p.x*u}" y="${y-(p.y+p.height)*u}" width="${p.width*u}" height="${p.height*u}" fill="none" stroke="#183430" stroke-width="2.5"/>`).join('');
 return `<figure class="cframe-figure"><svg viewBox="0 0 400 340" role="img" aria-labelledby="cframe-art-title"><title id="cframe-art-title">${example?'Example original':'Original'} rectangle ${m.originalWidth} by ${m.originalHeight} length units. ${example?'Example copy':'Copy'} ${m.width} by ${m.height} length units. All corners remain right angles; both panels and the references use the same unit size.</title><rect x="${x}" y="${y-12*u}" width="${12*u}" height="${12*u}" fill="#f6faf7"/><g fill="none" stroke="#d3e4d9" stroke-width=".65">${grid}</g><path d="M${x} 18V${y}H302" fill="none" stroke="#cbdcd3" stroke-width="1.5"/><text x="${x}" y="${y+18}" font-size="12">0</text><text x="${x+12*u}" y="${y+18}" text-anchor="middle" font-size="12">12 across</text><text x="18" y="30" text-anchor="end" font-size="12">12</text><rect data-cframe-copy ${rect(m.width,m.height)} fill="#c5e3d9" stroke="#16645b" stroke-width="3"/>${cells}${panels}<rect data-cframe-original ${rect(m.originalWidth,m.originalHeight)} fill="none" stroke="#9c690d" stroke-width="3" stroke-dasharray="7 4"/><path data-cframe-angle d="M${x} ${y-8}H${x+8}V${y}" fill="none" stroke="#183430" stroke-width="1.5"/><path data-cframe-angle d="M${x+m.width*u-8} ${y}V${y-8}H${x+m.width*u}" fill="none" stroke="#183430" stroke-width="1.5"/><path data-cframe-angle d="M${x+8} ${y-m.height*u}V${y-m.height*u+8}H${x}" fill="none" stroke="#183430" stroke-width="1.5"/><path data-cframe-angle d="M${x+m.width*u-8} ${y-m.height*u}V${y-m.height*u+8}H${x+m.width*u}" fill="none" stroke="#183430" stroke-width="1.5"/><text x="${x}" y="${y-m.height*u-7}" text-anchor="start" font-size="13" fill="#183430">Width ${m.width}</text><text x="${x+6}" y="${y+38}" font-size="13">Height ${m.height}; four right angles</text><path data-cframe-unit d="M330 48H352M330 43V53M352 43V53" fill="none" stroke="#183430" stroke-width="2"/><text x="320" y="71" font-size="11">1 length unit</text><rect data-cframe-square x="330" y="105" width="22" height="22" fill="#eaf4ef" stroke="#183430" stroke-width="2"/><text x="320" y="145" font-size="11">1 square unit</text><rect x="318" y="169" width="76" height="20" fill="none" stroke="#9c690d" stroke-dasharray="5 3"/><text x="321" y="183" font-size="11">Original</text><rect x="318" y="200" width="76" height="20" fill="#c5e3d9" stroke="#16645b"/><text x="321" y="214" font-size="11">${example?'Example copy':'My copy'}</text></svg><figcaption data-cframe-read>${example?copy.exampleLegend:copy.legend} ${tiles?'Shown cells each cover 1 square unit. ':''}${m.panels?.length?'The four bold outlined panels each have the original 2-by-3 dimensions.':''}</figcaption></figure>`;
}
function controls(m,entry){return `<div class="cframe-tools"><div class="cframe-edges" role="group" aria-label="Change the copy’s lengths">${button('width-less','Width −1',!m.canWidthLess,'cframe-limits')}${button('width-more','Width +1',!m.canWidthMore,'cframe-limits')}${button('height-less','Height −1',!m.canHeightLess,'cframe-limits')}${button('height-more','Height +1',!m.canHeightMore,'cframe-limits')}</div><div class="cframe-buttons">${button('turn','Turn copy')}${button('reset','Reset copy')}${button('tiles',entry.tiles?'Hide area squares':'Show area squares')}</div><p id="cframe-limits" class="cframe-limit" data-cframe-read>${copy.limit}</p><p class="cframe-turn-note">${copy.turn}</p></div>`;}
function comparison(m,material){return `<div class="cframe-comparison" id="cframe-comparison" tabindex="-1" data-cframe-read><h3>Compare these panels</h3> <table><thead><tr><th scope="col">Measure</th> <th scope="col">Original</th> <th scope="col">My copy</th> <th scope="col">Factor</th></tr></thead> <tbody>${m.sides.map(s=>`<tr><th scope="row">Original ${s.originalSide} to copy ${s.copySide}</th> <td data-label="Original">${copyLength(s.from)}</td> <td data-label="My copy">${copyLength(s.to)}</td> <td data-label="Factor">×${copyFactorText(s.factor)}</td></tr>`).join(' ')} <tr><th scope="row">Area</th> <td data-label="Original">${copyArea(m.originalArea)}</td> <td data-label="My copy">${copyArea(m.area)}</td> <td data-label="Factor">×${copyFactorText(m.areaFactor)}</td></tr></tbody></table> <p>${esc(copyFrameReading(material))}</p> <p class="cframe-boundary">${copy.boundary}</p></div>`;}
function liveBoard(v,entry){
 const m=copyFrameModel(entry.material),c=copyFrameCase(v.caseId);
 return `<h2 id="cframe-title" tabindex="-1" data-cframe-read>${esc(c.prompt)}</h2><p class="cframe-teaching" data-cframe-read>${copy.teaching}</p>${references(m)}<div class="cframe-workbench">${controls(m,entry)}${drawing(m,entry.tiles)}</div><div class="cframe-buttons">${button('compare','Compare measures')}${button('example','Show another example')}${hearButton('','Hear this copy')}</div>${entry.read?comparison(m,entry.material):''}`;
}
function exampleBoard(v){const m=copyFrameExample(v.frame);return `<h2 id="cframe-title" tabindex="-1" data-cframe-read>${copy.exampleTitle}</h2><p data-cframe-read>${copy.exampleNotice}</p><div class="cframe-buttons">${button('previous','Previous picture',v.frame===0)}${button('next','Next picture',v.frame===3)}${button('close','Return to my copy')}${hearButton('','Hear this example')}</div><p data-cframe-read>Worked example, picture ${m.displayIndex} of 4. ${esc(m.text)}</p>${references(m,true)}<div class="cframe-example-art">${drawing(m,true,true)}</div>`;}
export function copyFramePage(notebook,owner){const v=current(notebook,owner),entry=v.cases.get(v.caseId);return `<section class="panel cframe-board" data-cframe-root data-cframe-view="${v.example?'example':'live'}"><div class="section-heading"><div><h1>${copy.title}</h1><p data-cframe-read>${copy.opening}</p></div><a class="pill" href="#workshop">Workshop</a></div><label class="cframe-selector">Choose a panel <select data-cframe-case>${copyFrameCases.map(c=>`<option value="${c.id}"${c.id===v.caseId?' selected':''}>${c.title}</option>`).join('')}</select></label>${v.example?exampleBoard(v):liveBoard(v,entry)}<p class="cframe-status" role="status" aria-live="polite" aria-atomic="true"></p><p class="cframe-visit">${copy.visit}</p><a class="pill" href="#workshop/hinge">Explore turns and right angles</a><a class="pill" href="#workshop/same-ground">Try the same area with a different fence</a><details><summary>For grown-ups</summary><p>${copy.grownup}</p></details></section>`;}
export function bindCopyFrame(notebook,ctx){
 const root=document.querySelector('[data-cframe-root]');if(!root||!visit)return;
 const v=visit,owner=v.owner,id=v.caseId,entry=v.cases.get(id),material=entry.material,example=v.example,frame=v.frame;
 const live=()=>root.isConnected&&document.querySelector('[data-cframe-root]')===root&&location.hash==='#workshop/copy-frame'&&visit===v&&v.caseId===id&&v.cases.get(id)===entry&&entry.material===material&&v.example===example&&v.frame===frame&&(!ctx.isActive||ctx.isActive())&&ctx.notebook()===notebook&&ctx.explorerId()===owner;
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};
 if(v.pending)requestAnimationFrame(()=>requestAnimationFrame(()=>{if(live()){root.querySelector('.cframe-status').textContent=v.pending;v.pending='';}}));
 function redraw(selector='#cframe-title'){ctx.render();const candidate=document.querySelector(selector),node=candidate&&!candidate.disabled?candidate:document.querySelector('#cframe-title');if(node){node.focus({preventScroll:true});const box=node.getBoundingClientRect();if(box.top<0||box.bottom>innerHeight)node.scrollIntoView({block:'nearest'});}}
 const sizeMessage=(m,side='width')=>side==='height'?`Height is now ${copyLength(m.height)}. Width is ${copyLength(m.width)}.`:`Width is now ${copyLength(m.width)}. Height is ${copyLength(m.height)}.`;
 function edit(next,action,side){if(!next)return;stop();entry.material=next;entry.read=false;const m=copyFrameModel(next);v.pending=action==='turn'?`Copy turned and lined up again. Width: ${copyLength(m.width)}. Height: ${copyLength(m.height)}. Area stays ${copyArea(m.area)}.`:action==='reset'?'Copy returned to the original dimensions.':sizeMessage(m,side);let focus=action;if(action==='width-less'&&!m.canWidthLess)focus='width-more';if(action==='width-more'&&!m.canWidthMore)focus='width-less';if(action==='height-less'&&!m.canHeightLess)focus='height-more';if(action==='height-more'&&!m.canHeightMore)focus='height-less';redraw(`[data-cframe-action="${focus}"]`);}
 root.querySelector('[data-cframe-case]').addEventListener('change',e=>{if(!live()||!copyFrameCase(e.target.value))return;stop();v.caseId=e.target.value;v.example=false;v.frame=0;v.pending='';if(!v.cases.has(v.caseId))v.cases.set(v.caseId,{material:createCopyFrame(v.caseId),tiles:false,read:false});redraw('[data-cframe-case]');});
 root.querySelectorAll('[data-cframe-action]').forEach(b=>b.addEventListener('click',()=>{
  if(!live()||b.disabled)return;const action=b.dataset.cframeAction;
  if(!example&&/^(width|height)-(less|more)$/.test(action)){const [side,direction]=action.split('-');edit(changeCopySide(material,side,direction==='less'?-1:1),action,side);return;}
  if(!example&&action==='turn'){edit(turnCopyFrame(material),action);return;}
  if(!example&&action==='reset'){edit(resetCopyMaterial(material),action);return;}
  if(!example&&action==='tiles'){stop();entry.tiles=!entry.tiles;v.pending=entry.tiles?'Area squares shown.':'Area squares hidden.';redraw('[data-cframe-action="tiles"]');}
  if(!example&&action==='compare'){stop();entry.read=true;const m=copyFrameModel(material);v.pending='Comparison shown. '+(!m.matching?'This rectangle has another shape.':m.scale.n===m.scale.d?'Same shape and size.':`Same shape at factor ${copyFactorText(m.scale)}.`);redraw('#cframe-comparison');}
  if(!example&&action==='example'){stop();v.example=true;v.frame=0;v.pending='Worked example, picture 1 of 4.';redraw();}
  if(example&&action==='close'){stop();v.example=false;v.pending='My copy restored.';redraw('[data-cframe-action="example"]');}
  if(example&&['previous','next'].includes(action)){const next=frame+(action==='next'?1:-1);if(!copyFrameExample(next))return;stop();v.frame=next;v.pending=`Worked example, picture ${next+1} of 4.`;redraw(next===0?'[data-cframe-action="next"]':next===3?'[data-cframe-action="previous"]':`[data-cframe-action="${action}"]`);}
 }));
 root.addEventListener('click',e=>{const b=e.target.closest('[data-speak]');if(!b||!root.contains(b))return;if(!live()){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=[...root.querySelectorAll('[data-cframe-read]')].map(x=>x.textContent.trim()).join(' ');},{capture:true});
}
